import { motionLimits } from "./motion";

/** Internal pure candidates only. No DOM, physics, public API or renderer eligibility. */
export type NumericValue = number | bigint;
export type NumberDisplay = { readonly kind: "raw" } | { readonly kind: "intl"; readonly formatter: Intl.NumberFormat };
export type ReelDirection = "trend" | "up" | "down" | "shortest";
export type ReadoutCause =
  | "independent"
  | "selection"
  | "query"
  | "filter"
  | "direct-input"
  | "reset"
  | "restore"
  | "unknown";
type Unavailable = "nonfinite" | "digits" | "parts" | "formatter" | "input";
export interface NumberColumn {
  /** Decimal exponent: units 0, tens 1, tenths -1. Never an array/value key. */
  readonly place: number;
  readonly identity: object;
  readonly digit: string;
  readonly start: number;
  readonly end: number;
}
export interface NumberSnapshot {
  readonly value: NumericValue;
  /** Authoritative exact output, including bidi literals and every significant digit. */
  readonly text: string;
  readonly parts: readonly Intl.NumberFormatPart[];
  readonly columns: readonly NumberColumn[] | null;
  readonly formatKey: string;
  readonly localeKey: string;
  readonly scaleKey: string;
  readonly unavailable?: Unavailable;
}
export interface ReelLane {
  readonly identity: object;
  readonly place: number;
  readonly direction: "up" | "down";
  /** Coordinates are cell heights, NOT pixels or authored motion parameters. */
  readonly outgoing: { readonly digit: string; readonly from: 0; readonly to: -1 | 1 } | null;
  readonly incoming: { readonly digit: string; readonly from: -1 | 1; readonly to: 0 } | null;
}
export interface NumberPlan {
  readonly snapshot: NumberSnapshot;
  readonly lanes: readonly ReelLane[];
  readonly trend: "up" | "down" | null;
  readonly changedColumns: number;
  readonly immediate:
    | Unavailable
    | "baseline"
    | "equal"
    | "domain"
    | "entity"
    | "format"
    | "scale"
    | "cause"
    | "no-trend"
    | "columns"
    | null;
}

const rawDisplay: NumberDisplay = { kind: "raw" };
const affixTypes = new Set([
  "minusSign",
  "plusSign",
  "percentSign",
  "currency",
  "unit",
  "literal",
  "compact",
  "exponentSeparator",
  "exponentMinusSign",
  "exponentInteger",
]);
const scaleTypes = new Set([
  "compact",
  "exponentSeparator",
  "exponentMinusSign",
  "exponentInteger",
  "currency",
  "unit",
]);

/** Only called on String(original numeric value), never arbitrary user strings. */
function rawParts(text: string): Intl.NumberFormatPart[] | null {
  const match = /^(-?)([0-9]+)(?:\.([0-9]+))?$/.exec(text);
  if (!match) return null;
  const parts: Intl.NumberFormatPart[] = [];
  if (match[1]) parts.push({ type: "minusSign", value: match[1] });
  parts.push({ type: "integer", value: match[2] as string });
  if (match[3]) parts.push({ type: "decimal", value: "." }, { type: "fraction", value: match[3] });
  return parts;
}

/** Format once per committed target, never per animation frame. Formatting errors propagate. */
export function createNumberSnapshot(value: NumericValue, display: NumberDisplay = rawDisplay): NumberSnapshot {
  if (typeof value !== "number" && typeof value !== "bigint")
    throw new TypeError("Expected an original number or bigint");
  const text = display.kind === "raw" ? String(value) : display.formatter.format(value);
  let formatKey = "raw",
    localeKey = "raw",
    scaleKey = "raw";
  const fallback = (unavailable: Unavailable, parts: readonly Intl.NumberFormatPart[] = []): NumberSnapshot => ({
    value,
    text,
    parts,
    columns: null,
    formatKey,
    localeKey,
    scaleKey,
    unavailable,
  });
  if (typeof value === "number" && !Number.isFinite(value)) return fallback("nonfinite");
  // Reuse the conservative text-input ceiling BEFORE part/column decomposition.
  // Exact formatting itself is never truncated, even for a huge BigInt.
  if (text.length > motionLimits.diffInput) return fallback("input");
  let parts: readonly Intl.NumberFormatPart[];
  if (display.kind === "raw") {
    const parsed = rawParts(text);
    if (!parsed) return fallback("parts"); // Raw exponent spelling remains exact/immediate.
    parts = parsed;
  } else {
    try {
      // Custom/foreign part interpreters have no correspondence proof. Their
      // authoritative format() output still survives as an exact fallback.
      if (
        display.formatter.formatToParts !== Intl.NumberFormat.prototype.formatToParts ||
        display.formatter.resolvedOptions !== Intl.NumberFormat.prototype.resolvedOptions
      )
        return fallback("formatter");
      const options = display.formatter.resolvedOptions();
      formatKey = JSON.stringify(Object.entries(options).sort(([a], [b]) => a.localeCompare(b)));
      localeKey = JSON.stringify([options.locale, options.numberingSystem]);
      parts = display.formatter.formatToParts(value);
      if (parts.length > text.length || parts.map((part) => part.value).join("") !== text) return fallback("parts");
      if (options.numberingSystem !== "latn") return fallback("digits", parts);
      scaleKey = JSON.stringify(
        parts.filter((part) => scaleTypes.has(part.type)).map(({ type, value }) => [type, value]),
      );
    } catch {
      return fallback("formatter");
    }
  }
  let integerLength = 0,
    fractionLength = 0,
    decimal = false,
    offset = 0;
  for (let index = 0; index < parts.length; index++) {
    const part = parts[index];
    if (!part?.value) return fallback("parts", parts);
    if (part.type === "integer" || part.type === "fraction") {
      if (!/^[0-9]+$/.test(part.value)) return fallback("digits", parts);
      if (part.type === "integer") {
        if (decimal) return fallback("parts", parts);
        integerLength += part.value.length;
      } else {
        if (!decimal || fractionLength) return fallback("parts", parts);
        fractionLength += part.value.length;
      }
    } else if (part.type === "decimal") {
      if (decimal || !integerLength || parts[index + 1]?.type !== "fraction") return fallback("parts", parts);
      decimal = true;
    } else if (part.type === "group") {
      if (decimal || parts[index - 1]?.type !== "integer" || parts[index + 1]?.type !== "integer")
        return fallback("parts", parts);
    } else if (!affixTypes.has(part.type)) return fallback("parts", parts);
  }
  if (!integerLength) return fallback("parts", parts);
  const columns: NumberColumn[] = [];
  let integerIndex = 0,
    fractionIndex = 0;
  for (const part of parts) {
    if (part.type === "integer" || part.type === "fraction") {
      for (const digit of part.value) {
        const place = part.type === "integer" ? integerLength - ++integerIndex : -++fractionIndex;
        columns.push({ place, identity: {}, digit, start: offset, end: ++offset });
      }
    } else offset += part.value.length;
  }
  return { value, text, parts, columns, formatKey, localeKey, scaleKey };
}

/**
 * Compares exactly two committed snapshots. No origin-from-zero, target queue,
 * string inference or Number(bigint). Caller supplies accepted cause/entity truth.
 * A candidate still requires S12's native/layout/mode/continuity eligibility.
 */
export function planNumberChange(
  previous: NumberSnapshot | null,
  next: NumberSnapshot,
  options: { readonly direction?: ReelDirection; readonly cause?: ReadoutCause; readonly sameEntity?: boolean } = {},
): NumberPlan {
  let snapshot = next;
  const result = (
    immediate: NumberPlan["immediate"],
    trend: NumberPlan["trend"] = null,
    changedColumns = 0,
    lanes: readonly ReelLane[] = [],
  ): NumberPlan => ({ snapshot, immediate, trend, changedColumns, lanes });
  if (!previous) return result("baseline");
  if (options.sameEntity === false) return result("entity");
  if (typeof previous.value !== typeof next.value) return result("domain");
  if (
    previous.columns &&
    next.columns &&
    previous.localeKey === next.localeKey &&
    previous.scaleKey === next.scaleKey
  ) {
    const retained = new Map(previous.columns.map((column) => [column.place, column.identity]));
    snapshot = {
      ...next,
      columns: next.columns.map((column) => ({ ...column, identity: retained.get(column.place) ?? column.identity })),
    };
  }
  if (previous.text === next.text) return result("equal");
  if (next.unavailable || previous.unavailable) return result(next.unavailable ?? previous.unavailable ?? "parts");
  if (previous.formatKey !== next.formatKey) return result("format");
  if (previous.scaleKey !== next.scaleKey) return result("scale");
  if (options.cause !== "independent" && options.cause !== "selection") return result("cause");
  const trend = next.value > previous.value ? "up" : next.value < previous.value ? "down" : null;
  if (!trend) return result("no-trend"); // Includes -0↔0; sign is affix text only.
  const before = new Map(previous.columns?.map((column) => [column.place, column]));
  const after = new Map(snapshot.columns?.map((column) => [column.place, column]));
  let changedColumns = 0;
  for (const [place, column] of after) if (column.digit !== before.get(place)?.digit) changedColumns++;
  for (const place of before.keys()) if (!after.has(place)) changedColumns++;
  if (changedColumns > motionLimits.numericColumns) return result("columns", trend, changedColumns);
  const lanes: ReelLane[] = [];
  const lane = (old: NumberColumn | undefined, target: NumberColumn | undefined) => {
    if (old?.digit === target?.digit) return;
    let direction = options.direction ?? "trend";
    if (direction === "shortest" && old && target) {
      const up = (Number(target.digit) - Number(old.digit) + 10) % 10;
      direction = up <= 10 - up ? "up" : "down";
    }
    if (direction === "trend" || direction === "shortest") direction = trend;
    const edge = direction === "up" ? 1 : -1;
    const column = target ?? (old as NumberColumn);
    lanes.push({
      identity: column.identity,
      place: column.place,
      direction,
      outgoing: old ? { digit: old.digit, from: 0, to: edge === 1 ? -1 : 1 } : null,
      incoming: target ? { digit: target.digit, from: edge, to: 0 } : null,
    });
  };
  for (const [place, column] of after) lane(before.get(place), column);
  for (const [place, column] of before) if (!after.has(place)) lane(column, undefined);
  return result(null, trend, changedColumns, lanes);
}

/** Known finite transaction preflight, including still-live columns; S06 owns lifecycle. */
export function boundNumberRevision(
  plans: readonly NumberPlan[],
  active: ReadonlySet<object> = new Set(),
): readonly NumberPlan[] {
  if (!(active instanceof Set)) throw new RangeError("Numeric preflight requires a known identity Set");
  const identities = new Set<object>();
  let fits = active.size <= motionLimits.numericColumns;
  if (fits) {
    for (const identity of Set.prototype.values.call(active)) identities.add(identity);
    outer: for (const plan of plans)
      for (const lane of plan.lanes) {
        identities.add(lane.identity);
        if (identities.size > motionLimits.numericColumns) {
          fits = false;
          break outer;
        }
      }
  }
  return fits ? plans : plans.map((plan) => ({ ...plan, lanes: [], immediate: plan.immediate ?? "columns" }));
}

"use client";

import { animateSingleValue, motionValue, type Transition } from "motion/react";
import { bindMotionParameters, motionLimits, numberCompact, numberRoll, textProofLimits } from "./motion";
import { subscribeMotionEnvironment } from "./motion-environment";
import { createMotionTransaction, type MotionLease, type MotionRevision } from "./motion-transaction";
import {
  boundNumberRevision,
  type NumberPlan,
  type NumberSnapshot,
  planNumberChange,
  type ReadoutCause,
  type ReelDirection,
} from "./number-plan";
import type { CadenceMotion } from "./provider";
import type { TextSnapshot } from "./text-diff";
import {
  nativeTextContext,
  outgoingTextPaint,
  ownedTextHighlights,
  proveTextLayout,
  selectedTextContext,
} from "./text-layout";

export interface NumberPresentationCommit {
  snapshot: NumberSnapshot;
  revision: MotionRevision;
  cm: CadenceMotion;
  entity: unknown;
  cause?: ReadoutCause;
  direction?: ReelDirection;
  compact?: boolean;
  visible?: boolean;
  /** A separate geometry/fill engine cannot promise this reel's phase. The
   * composition shares the semantic revision but uses an immediate readout. */
  externalGeometry?: boolean;
}

let maskId = 0;
const clamp = (value: number) => Math.max(0, Math.min(1, value));
function textSnapshot(snapshot: NumberSnapshot): TextSnapshot {
  const columns = new Map(snapshot.columns?.map((column) => [column.start, column.identity]));
  return {
    value: snapshot.text,
    units: Array.from(snapshot.text, (text, index) => ({ text, identity: columns.get(index) ?? {} })),
  };
}

/** Internal renderer only. One native Text value; bounded, pixel-only two-cell
 * lanes. No geometry writer, DOM decomposition or frame-time formatting/layout.
 * Physical lifecycle is explicit; no document-removal scanner. */
export function createNumberPresentation(host: HTMLElement, transaction = createMotionTransaction()) {
  const doc = host.ownerDocument,
    view = doc.defaultView;
  const registration = transaction.register(host);
  let alive = true,
    baseline = true,
    editing = nativeTextContext(host),
    nativeOwned = false;
  let current: NumberPresentationCommit | null = null;
  let snapshot: NumberSnapshot | null = null;
  let lease: MotionLease | null = null;
  let generation = 0;
  let clock = "";
  let layer: HTMLElement | null = null;
  let mask: { name: string; highlight: Highlight; sheet: CSSStyleSheet } | null = null;
  let lanes: {
    identity: object;
    place: number;
    first: string | null;
    last: string | null;
    edge: number;
    phase: ReturnType<typeof motionValue<number>>;
    position: number;
    target: number;
    box: string;
    release(): void;
  }[] = [];
  const plain = () => host.childNodes.length <= 1 && (!host.firstChild || host.firstChild.nodeType === 3);
  const stop = () => {
    generation++;
    const old = lanes;
    lanes = [];
    for (const lane of old) {
      lane.phase.stop();
      lane.release();
    }
    if (mask) {
      if (view?.CSS.highlights.get(mask.name) === mask.highlight) view.CSS.highlights.delete(mask.name);
      ownedTextHighlights(doc).delete(mask.highlight);
      doc.adoptedStyleSheets = doc.adoptedStyleSheets.filter((sheet) => sheet !== mask?.sheet);
      mask = null;
    }
    layer?.remove();
    layer = null;
    lease?.finish();
    lease = null;
  };
  const restrict = () => {
    const next = nativeTextContext(host);
    if (editing !== next) {
      editing = next;
      nativeOwned = false;
      baseline = true;
      snapshot = null;
      stop();
    }
    if (
      !plain() ||
      editing ||
      selectedTextContext(host) ||
      !host.isConnected ||
      host.closest('[hidden],[inert],[aria-hidden="true"]')
    )
      stop();
  };
  const chain: HTMLElement[] = [];
  const transition = (event: TransitionEvent) => {
    // A sibling's hover/focus transition does not move or repaint this glyph.
    if (chain.includes(event.target as HTMLElement)) stop();
  };
  const observer = new MutationObserver((changes) => {
    stop();
    restrict();
    if (changes.some((change) => change.type !== "attributes")) {
      snapshot = null;
      baseline = true;
    }
  });
  for (let node: HTMLElement | null = host; node; node = node.parentElement) {
    chain.push(node);
    observer.observe(node, {
      attributes: true,
      attributeFilter: ["class", "style", "hidden", "inert", "aria-hidden", "dir", "contenteditable"],
    });
    node.addEventListener("transitionrun", transition, true);
  }
  observer.observe(host, {
    attributes: true,
    attributeFilter: ["class", "style", "hidden", "inert", "aria-hidden", "dir", "contenteditable"],
    childList: true,
    characterData: true,
    subtree: true,
  });
  let expectedSize = host.getBoundingClientRect();
  const resize = new ResizeObserver(() => {
    const box = host.getBoundingClientRect();
    if (box.width !== expectedSize.width || box.height !== expectedSize.height) stop();
    expectedSize = box;
  });
  resize.observe(host);
  const selection = () => {
    if (selectedTextContext(host)) stop();
  };
  const key = (event: KeyboardEvent) => {
    if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "f") stop();
  };
  const nativeInput = () => {
    nativeOwned = true;
    stop();
  };
  for (const name of ["beforeinput", "compositionstart"]) host.addEventListener(name, nativeInput, true);
  for (const name of ["copy", "beforematch"]) host.addEventListener(name, stop, true);
  doc.addEventListener("selectionchange", selection);
  doc.addEventListener("keydown", key, true);
  doc.addEventListener("scroll", stop, true);
  view?.addEventListener("resize", stop);
  view?.visualViewport?.addEventListener("resize", stop);
  view?.visualViewport?.addEventListener("scroll", stop);
  doc.fonts?.addEventListener("loadingdone", stop);
  let blocked = false;
  const unsubscribe = subscribeMotionEnvironment(doc, (environment) => {
    blocked = environment.hidden || environment.immediate || environment.reduced || environment.themeOwned;
    if (blocked) stop();
  });

  // Minimal native edit, retaining the Text node and native selection endpoints.
  // Editing commands/undo are never called, and no synthetic event is emitted.
  const exact = (value: string) => {
    let text = host.firstChild as Text | null;
    if (!text) {
      text = doc.createTextNode("");
      host.append(text);
    }
    if (text.data !== value) {
      let start = 0,
        end = 0;
      while (start < text.length && start < value.length && text.data[start] === value[start]) start++;
      while (
        end < text.length - start &&
        end < value.length - start &&
        text.data[text.length - 1 - end] === value[value.length - 1 - end]
      )
        end++;
      const oldEnd = text.length - end,
        newEnd = value.length - end;
      const selection = doc.getSelection();
      const saved =
        selection?.rangeCount === 1
          ? {
              anchor: selection.anchorNode,
              focus: selection.focusNode,
              a: selection.anchorOffset,
              f: selection.focusOffset,
            }
          : null;
      const map = (offset: number) => (offset <= start ? offset : offset >= oldEnd ? offset + newEnd - oldEnd : newEnd);
      text.replaceData(start, oldEnd - start, value.slice(start, newEnd));
      if (selection && saved && (saved.anchor === text || saved.focus === text))
        selection.setBaseAndExtent(
          saved.anchor as Node,
          saved.anchor === text ? map(saved.a) : saved.a,
          saved.focus as Node,
          saved.focus === text ? map(saved.f) : saved.f,
        );
    }
    observer.takeRecords();
    expectedSize = host.getBoundingClientRect();
    return text;
  };
  const preview = (options: NumberPresentationCommit) =>
    planNumberChange(snapshot, options.snapshot, {
      cause: options.cause,
      direction: options.direction,
      sameEntity: current !== null && Object.is(current.entity, options.entity),
    });
  const boxKey = (layout: NonNullable<ReturnType<typeof proveTextLayout>>, identity: object) => {
    const box = layout.boxes.get(identity);
    return box ? [box.left, box.top, box.width, box.height, layout.font, layout.color, layout.baseline].join("/") : "";
  };
  const play = (revision: MotionRevision, transition: Transition) => {
    const records = lanes;
    lease?.finish();
    lease = registration.begin(revision, ["number.roll"], { numericColumns: records.length }, stop);
    if (!lease?.current()) {
      stop();
      return;
    }
    const epoch = ++generation;
    let remaining = records.length;
    for (const record of records) {
      const from = record.position,
        velocity = record.phase.getVelocity();
      // Motion.stop() samples ahead to wall time. Rebase to the last actually
      // painted scalar; pass the reviewed velocity explicitly after jump resets it.
      record.phase.jump(from);
      animateSingleValue(record.phase, record.target, {
        ...transition,
        velocity: velocity * (record.target - from) > 0 ? velocity : 0,
        onUpdate: () => {
          // A retired delivery has no authority over a newer writer.
          if (alive && generation === epoch && !lease?.current()) stop();
        },
        onComplete: () => {
          if (alive && generation === epoch && lease?.current() && --remaining === 0) stop();
        },
      });
    }
  };
  return {
    preview,
    active: () => new Set(lanes.map((lane) => lane.identity)),
    commit(options: NumberPresentationCommit, allowed = true) {
      if (!alive) return;
      restrict();
      const previous = current;
      const plan = preview(options);
      const beforeSnapshot = snapshot;
      const { cm, revision } = options;
      const parameters = cm.parameters(
        bindMotionParameters(options.compact ? numberCompact : numberRoll, "number.roll/reels"),
      );
      const nextClock = parameters.kind === "reel" ? JSON.stringify(parameters.transition) : "";
      const retime = nextClock !== clock;
      clock = nextClock;
      const eligible =
        allowed &&
        revision.current() &&
        !baseline &&
        !blocked &&
        !editing &&
        !selectedTextContext(host) &&
        !cm.reduced &&
        cm.mode !== "none" &&
        cm.timeScale !== 0 &&
        options.visible !== false &&
        !options.externalGeometry &&
        parameters.kind === "reel" &&
        parameters.transition.duration !== 0;
      current = options;
      // Once native input owns this editor (or its buffer differs from the last
      // accepted prop), mode/clock/prop commits cannot restore display text.
      // Clean controlled display updates retain their existing native semantics.
      if (editing && host.textContent !== (previous?.snapshot.text ?? options.snapshot.text)) nativeOwned = true;
      if ((editing && nativeOwned) || !plain() || host.matches("input,textarea,select,option")) {
        stop();
        snapshot = null;
        baseline = true;
        return;
      }
      const equal =
        previous &&
        Object.is(previous.entity, options.entity) &&
        typeof beforeSnapshot?.value === typeof options.snapshot.value &&
        beforeSnapshot?.text === options.snapshot.text &&
        beforeSnapshot.formatKey === options.snapshot.formatKey &&
        beforeSnapshot.scaleKey === options.snapshot.scaleKey;
      if (equal) {
        snapshot = plan.snapshot;
        if (!eligible || (options.cause !== "independent" && options.cause !== "selection")) stop();
        else if (lanes.length && parameters.kind === "reel" && (retime || revision !== previous.revision))
          play(revision, parameters.transition);
        // Equal semantic output never measures, allocates, restarts or truncates a legal flight.
        return;
      }
      const identities = new Set([...lanes.map((lane) => lane.identity), ...plan.lanes.map((lane) => lane.identity)]);
      const others = [...transaction.activeWork("numericColumns")].reduce(
        (sum, [entity, count]) => sum + (entity === host ? 0 : count),
        0,
      );
      const overflow = identities.size + others > motionLimits.numericColumns;
      if (overflow)
        registration.begin(revision, ["number.roll"], { numericColumns: motionLimits.numericColumns + 1 }, stop);
      const canAnimate = eligible && !plan.immediate && !overflow;
      const before = canAnimate && beforeSnapshot ? proveTextLayout(host, textSnapshot(beforeSnapshot)) : null;
      const text = exact(plan.snapshot.text);
      snapshot = plan.snapshot;
      baseline = false;
      const after = before && proveTextLayout(host, textSnapshot(snapshot));
      observer.takeRecords();
      if (
        !before ||
        !after ||
        !view?.Highlight ||
        !view.CSSStyleSheet ||
        !view.CSS?.highlights ||
        parameters.kind !== "reel"
      ) {
        stop();
        return;
      }
      const highlights = view.CSS.highlights;
      const known = ownedTextHighlights(doc);
      if ([...highlights.values()].some((highlight) => !known.has(highlight))) {
        stop();
        return;
      }
      // A third visible digit cannot replace either current cell without a jump.
      // A reversal to the actual departing digit can reuse BOTH current offsets.
      const continuing =
        lanes.length > 0 &&
        plan.lanes.length === lanes.length &&
        plan.lanes.every((lane) => {
          const old = lanes.find((item) => item.identity === lane.identity);
          return (
            old &&
            (lane.incoming?.digit === old.first || lane.incoming?.digit === old.last) &&
            lane.direction === ((lane.incoming?.digit === old.last ? old.edge : -old.edge) === 1 ? "up" : "down") &&
            old.box === boxKey(after, lane.identity)
          );
        });
      if (lanes.length && !continuing) {
        stop();
        return;
      }
      const ranges: Range[] = [];
      for (const lane of plan.lanes) {
        const column = snapshot.columns?.find((column) => column.identity === lane.identity);
        if (column) {
          const range = doc.createRange();
          range.setStart(text, column.start);
          range.setEnd(text, column.end);
          ranges.push(range);
        }
      }
      const installMask = () => {
        if (mask) {
          highlights.delete(mask.name);
          known.delete(mask.highlight);
          doc.adoptedStyleSheets = doc.adoptedStyleSheets.filter((sheet) => sheet !== mask?.sheet);
          mask = null;
        }
        if (!ranges.length) return;
        const name = `cadence-number-${++maskId}`,
          sheet = new view.CSSStyleSheet(),
          highlight = new view.Highlight(...ranges);
        sheet.replaceSync(`::highlight(${name}) { color: transparent; }`);
        mask = { name, sheet, highlight };
        known.add(highlight);
        doc.adoptedStyleSheets = [...doc.adoptedStyleSheets, sheet];
        highlights.set(name, highlight);
        if (view.getComputedStyle(host, `::highlight(${name})`).color !== "rgba(0, 0, 0, 0)")
          throw new Error("Numeric mask unavailable");
      };
      try {
        if (!continuing) {
          stop();
          layer = doc.createElement("span");
          layer.inert = true;
          layer.setAttribute("aria-hidden", "true");
          layer.dataset.cadenceNumberLayer = "";
          layer.dataset.cadenceNumberOwner = host.id;
          layer.dataset.motion = cm.mode;
          Object.assign(layer.style, {
            position: "fixed",
            inset: "0",
            contain: "strict",
            overflow: "clip",
            pointerEvents: "none",
            userSelect: "none",
            overflowAnchor: "none",
          });
          let pixels = 0;
          for (const lane of plan.lanes) {
            const a = before.boxes.get(lane.identity),
              b = after.boxes.get(lane.identity),
              box = b ?? a;
            if (!box || (a && b && (a.top !== b.top || a.height !== b.height))) throw new Error("Numeric line changed");
            const left = Math.min(a?.left ?? box.left, b?.left ?? box.left),
              right = Math.max(
                (a?.left ?? box.left) + (a?.width ?? box.width),
                (b?.left ?? box.left) + (b?.width ?? box.width),
              );
            if (
              left < 0 ||
              box.top < 0 ||
              right > view.innerWidth ||
              box.top + box.height > view.innerHeight ||
              chain.some((node) => {
                const css = view.getComputedStyle(node),
                  clip = node.getBoundingClientRect();
                return (
                  /(auto|scroll|hidden|clip)/.test(`${css.overflowX} ${css.overflowY}`) &&
                  (left < clip.left || right > clip.right || box.top < clip.top || box.top + box.height > clip.bottom)
                );
              })
            )
              throw new Error("Numeric clipping unavailable");
            const clip = doc.createElement("span");
            clip.dataset.cadenceReel = String(lane.place);
            clip.dataset.motion = cm.mode;
            Object.assign(clip.style, {
              position: "absolute",
              left: "0",
              top: `${box.top}px`,
              width: `${view.innerWidth}px`,
              height: `${box.height}px`,
              overflow: "clip",
            });
            const paints: { canvas: HTMLCanvasElement; incoming: boolean; top: number }[] = [];
            for (const incoming of [false, true]) {
              const digit = incoming ? lane.incoming?.digit : lane.outgoing?.digit;
              if (digit === undefined) continue;
              const layout = incoming ? after : before;
              const canvas = outgoingTextPaint(host, { text: digit, identity: lane.identity }, layout, true);
              if (!canvas) throw new Error("Numeric paint unavailable");
              pixels += canvas.width * canvas.height;
              if (pixels > textProofLimits.pixels) throw new Error("Numeric pixel capacity");
              canvas.removeAttribute("data-cadence-text-paint");
              canvas.dataset.cadenceNumberCell = incoming ? "target" : "departing";
              canvas.dataset.motion = cm.mode;
              const top = Number.parseFloat(canvas.style.top) - box.top;
              canvas.style.top = `${top}px`;
              clip.append(canvas);
              paints.push({ canvas, incoming, top });
            }
            const phase = motionValue(0),
              edge = lane.direction === "up" ? 1 : -1;
            const record = {
              identity: lane.identity,
              place: lane.place,
              first: lane.outgoing?.digit ?? null,
              last: lane.incoming?.digit ?? null,
              phase,
              position: 0,
              edge,
              target: 1,
              box: boxKey(after, lane.identity),
              release: () => {},
            };
            const update = () => {
              // Token overrides may overshoot. Painted travel stays monotonic
              // inside this revision's one-cell lane, never follows a rebound.
              const value =
                record.target === 1
                  ? Math.max(record.position, clamp(phase.get()))
                  : Math.min(record.position, clamp(phase.get()));
              record.position = value;
              clip.dataset.phase = String(value);
              for (const paint of paints)
                paint.canvas.style.transform = `translateY(${edge * (paint.incoming ? 1 - value : -value) * box.height}px)`;
            };
            record.release = phase.on("change", update);
            update();
            lanes.push(record);
            layer.append(clip);
          }
          doc.body.append(layer);
        }
        installMask();
        for (const record of lanes) {
          const target = continuing
            ? Number(plan.lanes.find((lane) => lane.identity === record.identity)?.incoming?.digit === record.last)
            : 1;
          record.target = target;
        }
        play(revision, parameters.transition);
      } catch {
        stop();
      } // Failure always exposes the exact current native text.
    },
    cancel: stop,
    dispose() {
      if (!alive) return;
      alive = false;
      stop();
      registration.dispose();
      observer.disconnect();
      resize.disconnect();
      unsubscribe();
      for (const name of ["beforeinput", "compositionstart"]) host.removeEventListener(name, nativeInput, true);
      for (const name of ["copy", "beforematch"]) host.removeEventListener(name, stop, true);
      doc.removeEventListener("selectionchange", selection);
      doc.removeEventListener("keydown", key, true);
      doc.removeEventListener("scroll", stop, true);
      view?.removeEventListener("resize", stop);
      view?.visualViewport?.removeEventListener("resize", stop);
      view?.visualViewport?.removeEventListener("scroll", stop);
      doc.fonts?.removeEventListener("loadingdone", stop);
      for (const node of chain) node.removeEventListener("transitionrun", transition, true);
    },
  };
}

/** Known finite composition preflight BEFORE any member measures/allocates.
 * Share options.revision with text/geometry/readout owners; independent caps
 * remain enforced by that same transaction, including still-active work. */
export function commitNumberPresentations(
  entries: readonly { controller: ReturnType<typeof createNumberPresentation>; options: NumberPresentationCommit }[],
) {
  const active = new Set(entries.flatMap(({ controller }) => [...controller.active()]));
  const plans: readonly NumberPlan[] = entries.map(({ controller, options }) => controller.preview(options));
  const bounded = boundNumberRevision(plans, active);
  const allowed = bounded.every((plan, index) => plan === plans[index]);
  for (const entry of entries) entry.controller.commit(entry.options, allowed);
}

"use client";

import { useEffect, useLayoutEffect, useRef } from "react";
import type { MotionHostRef } from "./motion-ref";
import { createMotionTransaction } from "./motion-transaction";
import { createNumberSnapshot, type NumberDisplay, type NumericValue } from "./number-plan";
import { createNumberPresentation, type NumberPresentationCommit } from "./number-presentation";
import type { CadenceMotion } from "./provider";

const committed = typeof window === "undefined" ? useEffect : useLayoutEffect;

/** Numeric display adapter. Return the actual SSR value once, retain one native
 * Text node and commit formatting only when accepted inputs change. */
export function useNumberPresentation(
  host: MotionHostRef<HTMLElement>,
  value: NumericValue,
  cm: CadenceMotion,
  entity: unknown,
  options: Partial<
    Pick<NumberPresentationCommit, "cause" | "direction" | "compact" | "visible" | "externalGeometry">
  > & { display?: NumberDisplay; revision?: NumberPresentationCommit["revision"] } = {},
  supplied?: ReturnType<typeof createMotionTransaction>,
) {
  const initial = useRef<string | null>(null);
  if (initial.current === null) initial.current = createNumberSnapshot(value, options.display).text;
  const local = useRef<ReturnType<typeof createMotionTransaction> | null>(null);
  if (!local.current) local.current = createMotionTransaction();
  const transaction = supplied ?? local.current;
  const connected = useRef<{
    element: HTMLElement;
    identity: object | undefined;
    transaction: typeof transaction;
    controller: ReturnType<typeof createNumberPresentation>;
    source: object;
    value?: NumericValue;
    display?: NumberDisplay;
    snapshot?: ReturnType<typeof createNumberSnapshot>;
  } | null>(null);
  committed(() => {
    const old = connected.current;
    if (old && (old.element !== host.current || old.identity !== host.identity || old.transaction !== transaction)) {
      connected.current = null;
      old.controller.dispose();
    }
    if (!connected.current && host.current)
      connected.current = {
        element: host.current,
        identity: host.identity,
        transaction,
        controller: createNumberPresentation(host.current, transaction),
        source: {},
      };
    const connection = connected.current;
    host.invalidate = () => {
      connected.current = null;
      connection?.controller.dispose();
    };
    if (!connection) return;
    if (!connection.snapshot || !Object.is(value, connection.value) || options.display !== connection.display) {
      connection.snapshot = createNumberSnapshot(value, options.display);
      connection.value = value;
      connection.display = options.display;
    }
    connection.controller.commit({
      ...options,
      snapshot: connection.snapshot,
      entity,
      cm,
      visible: options.visible,
      revision: options.revision ?? transaction.revision("value", value, connection.source),
      direction: cm.reduced ? undefined : options.direction,
    });
  });
  committed(
    () => () => {
      const old = connected.current;
      connected.current = null;
      old?.controller.dispose();
      host.invalidate = undefined;
    },
    [host],
  );
  return initial.current;
}
